import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CYjxsSA2.js";const p=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"quickstart.md","filePath":"quickstart.md"}'),r={name:"quickstart.md"};function e(s,l,n,c,d,h){return i(),t("div",null,[...l[0]||(l[0]=[o('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>本章带您在十分钟内跑通一个完整流程：创建项目 → 配置模型 → 空间扫描 → 军团渗透 → 漏洞分诊与导出。</p><div class="warning custom-block"><p class="custom-block-title">前置条件</p><ul><li>已按 <a href="/vaelor/download.html">下载与安装</a> 解包并成功启动</li><li>测试目标为<strong>您已获得书面授权</strong>的系统（本地靶场亦可，如 DVWA）</li></ul></div><h2 id="第一步-创建项目" tabindex="-1">第一步：创建项目 <a class="header-anchor" href="#第一步-创建项目" aria-label="Permalink to &quot;第一步：创建项目&quot;">​</a></h2><ol><li>启动主程序，进入首页（项目列表）</li><li>点<strong>新建项目</strong>，填写项目名称（如 <code>某授权项目 - 一期</code>）</li><li>进入项目即可开工 —— 目标在下发扫描或交给军团时直接填写，平台会自动把它登记到项目里</li></ol><p>所有模块的数据都归属于当前项目，互不串扰。项目内左侧是 7 个执行面板：仪表盘 / 军团 / 漏洞管理 / 漏洞测绘 / 云上综合 / 空间扫描 / 空间测绘。</p><h2 id="第二步-配置大模型" tabindex="-1">第二步：配置大模型 <a class="header-anchor" href="#第二步-配置大模型" aria-label="Permalink to &quot;第二步：配置大模型&quot;">​</a></h2><p>军团需要一个大模型 Provider 才能工作：</p><ol><li>打开<strong>系统配置 → 大模型配置</strong></li><li>新建或启用一个 Provider，填写接口格式（OpenAI 兼容 / Anthropic Claude 等）、Base URL 与 API Key</li><li>保存后可先做一次连通性验证</li></ol><div class="tip custom-block"><p class="custom-block-title">建议</p><p>推荐选择支持**函数调用（Tool Use）**的模型，军团的工具调度体验最佳。若遇到「大模型连接失败」，先调大模型请求超时与流式空闲超时。</p></div><h2 id="第三步-空间扫描" tabindex="-1">第三步：空间扫描 <a class="header-anchor" href="#第三步-空间扫描" aria-label="Permalink to &quot;第三步：空间扫描&quot;">​</a></h2><ol><li>打开项目的<strong>空间扫描</strong>页</li><li>填写目标（支持 IP / CIDR / 域名），选一个端口模板</li><li>点击开始扫描，实时查看端口、服务、Web 标题、TLS 证书与 IP 归属</li><li>扫描结束后，开放 Web 服务的端口可联动<strong>漏洞测绘</strong>做站点分析</li></ol><h2 id="第四步-军团渗透" tabindex="-1">第四步：军团渗透 <a class="header-anchor" href="#第四步-军团渗透" aria-label="Permalink to &quot;第四步：军团渗透&quot;">​</a></h2><ol><li><p>打开项目的<strong>军团</strong>页，在会话列表新建会话，选择合适的角色（红队 / 渗透 / CTF / 侦察）</p></li><li><p>用一句话下达任务，例如：</p><blockquote><p>对 10.1.5.1 进行授权渗透测试，目标是发现并验证全部可利用的漏洞，输出报告。</p></blockquote></li><li><p>观察军团自动推进：拆解任务、并行验证、回收结论，直到任务完成</p></li><li><p>每次探测、截图、证据提交都会留痕；右侧面板可查看并行任务、浏览器画面与工具调用记录</p></li></ol><details><summary>军团可能自动做了什么？</summary><ul><li>端口扫描与服务识别</li><li>对发现的 Web 站点做指纹与目录探测</li><li>通过测绘结果定位可疑入口</li><li>用浏览器登录、截图、抓取动态内容</li><li>调用 Kali / WSL 工具箱执行内网命令（如已配置）</li><li>把验证过的发现写入漏洞账本</li></ul></details><div class="tip custom-block"><p class="custom-block-title">想更稳妥地开跑</p><ul><li><strong>先看计划</strong>：点输入框的<strong>计划</strong>按钮，军团只做被动侦察并给出一份计划，确认后点「批准并执行」</li><li><strong>收紧权限</strong>：点<strong>权限</strong>按钮切到「只读」或「工作区写入」，命令执行与写操作会被拦截</li><li><strong>强制隔离</strong>：在系统配置 → 智能体 → 执行环境中选「必须隔离」，没有容器时命令直接拒绝执行</li></ul></div><h2 id="第五步-漏洞分诊与导出" tabindex="-1">第五步：漏洞分诊与导出 <a class="header-anchor" href="#第五步-漏洞分诊与导出" aria-label="Permalink to &quot;第五步：漏洞分诊与导出&quot;">​</a></h2><p>进入项目的<strong>漏洞管理</strong>页：</p><ul><li><strong>发现</strong> 页签按严重度分诊：顶部风险带看整体态势，下面是档位泳道，每条发现可展开证据、跳回产生它的会话</li><li><strong>侦察报告</strong> 页签按资产归集，可单个或批量导出 Markdown / PDF</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/vaelor/guide/project.html">项目管理</a> — 项目、目标与仪表盘</li><li><a href="/vaelor/guide/army.html">军团智能体</a> — 计划模式、权限与角色</li><li><a href="/vaelor/advanced/docker.html">Kali 工具箱</a> — 内网作战环境</li></ul>',21)])])}const g=a(r,[["render",e]]);export{p as __pageData,g as default};
